#!/usr/bin/env python3
import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
ET.register_namespace("hp", HP_NS)


def _localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _digits_only(value) -> str:
    s = "" if value is None else str(value)
    digits = re.findall(r"\d+", s)
    return "".join(digits)


def _parse_first_float(value) -> float:
    if isinstance(value, (int, float)):
        return float(value)
    s = "" if value is None else str(value)
    m = re.search(r"(\d+(?:\.\d+)?)", s)
    if not m:
        raise ValueError(f"Could not parse numeric score from 만족도={value!r}")
    return float(m.group(1))


def _append_followup(sentence: str) -> str:
    followup = "후속 심화반 검토 요망."
    if sentence is None:
        sentence = ""
    s = str(sentence).rstrip()
    if not s:
        return followup
    if s.endswith(followup):
        return s
    # Ensure exactly one space before the followup sentence.
    return s + " " + followup


def build_substitutions(data: dict) -> dict:
    subs = {k: ("" if v is None else str(v)) for k, v in data.items()}

    if "참석자수" in subs:
        subs["참석자수"] = _digits_only(data.get("참석자수"))

    if "만족도" in subs:
        score = _parse_first_float(data.get("만족도"))
        subs["만족도"] = f"{score:.1f}점 (5.0점 만점)"

    if "종합의견" in subs:
        subs["종합의견"] = _append_followup(data.get("종합의견"))

    return subs


def _remove_layout_cache(elem: ET.Element) -> None:
    """Remove stale layout-cache elements under elem (in-place)."""
    for child in list(elem):
        ln = _localname(child.tag)
        if ln in {"linesegarray", "lineseg"}:
            elem.remove(child)
            continue
        _remove_layout_cache(child)


def _fill_placeholders_in_paragraph(p: ET.Element, subs: dict) -> bool:
    """Fill placeholders inside one <hp:p>. Returns True if modified."""
    text_nodes = [t for t in p.iter() if _localname(t.tag) == "t"]
    if not text_nodes:
        return False

    original = "".join((t.text or "") for t in text_nodes)
    new = original

    # Replace all {{key}} occurrences we can.
    def repl(m: re.Match) -> str:
        key = m.group(1)
        if key in subs:
            return subs[key]
        return m.group(0)  # leave untouched for now

    new = re.sub(r"\{\{([^{}]+)\}\}", repl, new)

    if new == original:
        return False

    # Write the full new text into the first run, clear the rest.
    text_nodes[0].text = new
    for t in text_nodes[1:]:
        t.text = ""

    # Critical: remove stale layout caches for modified paragraphs.
    _remove_layout_cache(p)
    return True


def fill_hwpx(template_hwpx_path: str, json_path: str, out_hwpx_path: str) -> None:
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    subs = build_substitutions(data)

    with zipfile.ZipFile(template_hwpx_path, "r") as zin:
        names = zin.namelist()

        # If present, write mimetype first and uncompressed (ODF-style convention).
        mimetype_first = [n for n in names if n == "mimetype"]
        rest = [n for n in names if n != "mimetype"]
        ordered = mimetype_first + rest

        with zipfile.ZipFile(out_hwpx_path, "w") as zout:
            for name in ordered:
                raw = zin.read(name)

                if name.lower().endswith(".xml"):
                    xml_text = raw.decode("utf-8", "replace")
                    root = ET.fromstring(xml_text)

                    modified_any = False
                    for p in root.iter():
                        if _localname(p.tag) == "p":
                            if _fill_placeholders_in_paragraph(p, subs):
                                modified_any = True

                    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)

                    # Safety net: replace any remaining intact {{key}} sequences outside <hp:p>.
                    out_text = out_bytes.decode("utf-8", "replace")
                    for k, v in subs.items():
                        out_text = out_text.replace("{{" + k + "}}", v)
                    out_bytes = out_text.encode("utf-8")

                    zi = zipfile.ZipInfo(name)
                    zi.compress_type = zipfile.ZIP_DEFLATED
                    zout.writestr(zi, out_bytes)
                elif name == "mimetype":
                    zi = zipfile.ZipInfo(name)
                    zi.compress_type = zipfile.ZIP_STORED
                    zout.writestr(zi, raw)
                else:
                    zi = zipfile.ZipInfo(name)
                    zi.compress_type = zipfile.ZIP_DEFLATED
                    zout.writestr(zi, raw)


def main(argv: list[str]) -> int:
    if len(argv) != 4:
        print(
            "Usage: fill_training_feedback_hwpx.py <template.hwpx> <training_feedback.json> <out.hwpx>",
            file=sys.stderr,
        )
        return 2

    template, json_path, out_path = argv[1], argv[2], argv[3]
    fill_hwpx(template, json_path, out_path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

